package glitch

import data.glitch_lib

# High-privilege execution contexts
high_privilege_contexts := {"root", "admin", "administrator", "system", "sudo", "privileged"}

# Broad scope indicators
broad_scope_indicators := {"*", "all", "global", "any"}

# Privileged container/security context indicators
privileged_container_indicators := {"privileged", "host_network", "host_pid", "host_ipc", "allow_privilege_escalation"}

# High-role assignments
high_roles := {"owner", "admin", "administrator", "cluster_admin", "cluster-admin"}

# Check if value indicates high privilege context
is_high_privilege_context(value) {
    value.ir_type == "String"
    lower(value.value) == high_privilege_contexts[_]
} else {
    value.ir_type == "Boolean"
    value.value == true
    value.name == "privileged"
}

# Check if value indicates broad scope
is_broad_scope(value) {
    value.ir_type == "String"
    lower(value.value) == broad_scope_indicators[_]
}

# Check if value is a high privilege role
is_high_role(value) {
    value.ir_type == "String"
    contains(lower(value.value), high_roles[_])
}

# Check for privileged security context attributes
is_privileged_security_context(attr) {
    lower(attr.name) == privileged_container_indicators[_]
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

# Check for capabilities with ALL or wildcard
is_excessive_capabilities(value) {
    value.ir_type == "String"
    upper(value.value) == "ALL"
} else {
    value.ir_type == "String"
    value.value == "*"
}

# Check for host path mounts
is_host_path_mount(attr) {
    lower(attr.name) == "host_path"
} else {
    lower(attr.name) == "hostpath"
}

# Check for role/permission with broad resource/action scope
is_broad_permission_attribute(attr) {
    lower(attr.name) == "role"
    is_high_role(attr.value)
} else {
    lower(attr.name) == "scope"
    is_broad_scope(attr.value)
} else {
    lower(attr.name) == "resource"
    is_broad_scope(attr.value)
} else {
    lower(attr.name) == "action"
    is_broad_scope(attr.value)
}

# Recursively check for privileged configuration in nested structures
has_privileged_config(node) {
    walk(node, [_, n])
    n.ir_type == "Attribute"
    is_high_privilege_context(n.value)
} else {
    walk(node, [_, n])
    n.ir_type == "Attribute"
    is_privileged_security_context(n)
} else {
    walk(node, [_, n])
    n.ir_type == "Attribute"
    lower(n.name) == "capabilities"
    is_excessive_capabilities(n.value)
}

# Recursively check for broad scope in nested structures
has_broad_scope_config(node) {
    walk(node, [_, n])
    n.ir_type == "Attribute"
    is_broad_permission_attribute(n)
} else {
    walk(node, [_, n])
    n.ir_type == "Attribute"
    is_host_path_mount(n)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check for privileged execution context with broad scope
    has_privileged_config(node)
    has_broad_scope_config(node)

    result := {
        "type": "sec_def_admin",
        "element": node,
        "path": parent.path,
        "description": "Execution with Unnecessary Privileges - The configuration uses elevated privileges with broad resource scope when more restrictive permissions would suffice. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check for privileged container configuration
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Direct privileged flag
    lower(attr.name) == "privileged"
    attr.value.ir_type == "Boolean"
    attr.value.value == true

    # Check if also has host namespace sharing or privilege escalation
    other_attr := attrs[_]
    other_attr != attr
    is_privileged_security_context(other_attr)

    result := {
        "type": "sec_def_admin",
        "element": node,
        "path": parent.path,
        "description": "Execution with Unnecessary Privileges - Container configuration uses privileged mode with unnecessary host namespace sharing. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check for excessive role assignments
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # High role assignment
    lower(attr.name) == "role"
    is_high_role(attr.value)

    # Check for broad scope in same node
    other_attr := attrs[_]
    other_attr != attr
    lower(other_attr.name) == "scope"
    is_broad_scope(other_attr.value)

    result := {
