        "element": attr,
        "path": parent.path,
        "description": "Execution with Unnecessary Privileges - High-privilege role assigned with unrestricted scope. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check for root user with write/delete permissions
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

