    value.ir_type == "String"
    lower(value.value) == "root"

    # Check for broad permissions
    other_attr := attrs[_]
    other_attr != attr
    lower(other_attr.name) == "permissions"
    is_broad_scope(other_attr.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Execution with Unnecessary Privileges - Root user execution with excessively broad permissions. (CWE-250)"
    }
}

