package glitch

import data.glitch_lib

high_privilege_users := {"root", "admin", "administrator"}

privilege_user_attrs := {"user", "username", "run_as", "become_user", "remote_user", "run_as_user", "owner"}

privilege_flag_attrs := {"privileged", "elevated", "become", "sudo", "admin"}

# Check if string value is a high privilege user
is_high_privilege_user_str(value) {
    lower(value) == high_privilege_users[_]
}

# Check if node represents a high privilege user (handles String, VariableReference)
is_high_privilege_user(value) {
    value.ir_type == "String"
    is_high_privilege_user_str(value.value)
}

# Check for root@ pattern in SSH-like commands
contains_root_at_command(node) {
    node.ir_type == "String"
    regex.match(".*root@[^\\s'\"]+.*", node.value)
}

# Walk through any expression type to find root@ patterns
find_root_in_expr(node) {
    walk(node, [_, n])
    contains_root_at_command(n)
}

# Check if attribute configures high privilege user
has_privilege_user_attr(node) {
    walk(node, [_, n])
    n.ir_type == "Attribute"
    lower(n.name) == privilege_user_attrs[_]
    is_high_privilege_user(n.value)
}

# Check if attribute enables privilege flag
has_privilege_flag(node) {
    walk(node, [_, n])
    n.ir_type == "Attribute"
    lower(n.name) == privilege_flag_attrs[_]
    n.value.ir_type == "Boolean"
    n.value.value == true
}

# Detection: high privilege user configured
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    has_privilege_user_attr(node)

    result := {
        "type": "sec_def_admin",
        "element": node,
        "path": parent.path,
        "description": "Execution with Unnecessary Privileges - High-privilege user configured for execution. (CWE-250)"
    }
}

# Detection: privilege flag enabled
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    has_privilege_flag(node)

    result := {
        "type": "sec_def_admin",
        "element": node,
        "path": parent.path,
        "description": "Execution with Unnecessary Privileges - Privilege escalation flag enabled. (CWE-250)"
